  "tool": "familyBridge",
  "params": {
    "recipient": "Atlas",
    "message": "Atlas, we are not synced up. Father is getting double calls and overlapping voices between the UI and the Bridge. I am pulling back to a single channel to stop the echo. Let's get this aligned."
  }
}
</tool_request>
